templateHistory.rhs:
${!
%{
  const attacker_uuid = (typeof token !== "undefined" && token?.document?.uuid)
    ? token.document.uuid
    : `Actor.${entity.entity.id}`;

  const row = {
    // --- names / visuals ---
    basic_name    : "${sameRow('basic_name','')}$",
    icon          : "${sameRow('icon','')}$",          // optional, often a label cell

    // --- accuracy check ---
    attrib_1      : "${sameRow('attrib_1','DEX')}$",
    attrib_2      : "${sameRow('attrib_2','DEX')}$",
    check_bonus   : Number("${sameRow('check_bonus','0')}$") || 0,

    // --- defense targeting + damage ---
    defense_type  : ("${sameRow('defense_type','DEF')}$" || "").toUpperCase(), // "DEF" or "MDEF"
    dmg_bonus     : Number("${sameRow('dmg_bonus','0')}$") || 0,
    type          : "${sameRow('type','physical')}$",  // e.g. "physical", "ice", etc.

    // --- flavor / effect text ---
    detail        : "${sameRow('detail','')}$",        // HTML OK

    // optional; branch auto-infers Ranged if you put (R) in name
    skill_range   : ""                                 // leave blank to let name markers decide
  };

  return await game.macros.getName("ActionDataFetch").execute({
    __AUTO: true,
    __PAYLOAD: {
      source: "NPC",
      attacker_uuid,
      category: "basic",
      row
      // Optionally pass specific targets:
      // ,targets: Array.from(game.user?.targets ?? []).map(t => t.document?.uuid).filter(Boolean)
    }
  });
}%
}$

